export const metadata = { title: "Владелец" };

function Tile({ label, value, hint }: { label: string; value: string | number; hint?: string }) {
  return (
    <div className="border-border bg-surface rounded-xl border px-4 py-3.5">
      <div className="text-text-subtle text-2xs">{label}</div>
      <div className="readout mt-1 text-xl">{value}</div>
      {hint ? <div className="text-text-subtle mt-0.5 text-2xs">{hint}</div> : null}
    </div>
  );
}

/**
 * Месяцы для переключателя: текущий и одиннадцать прошлых.
 *
 * Дальше года назад владелец в кабинет не ходит — для этого есть «Отчёты», где
 * период выбирается вручную; а длинный список месяцев сам по себе становится
 * меню, в котором надо искать.
 */
function monthChoices(now: Date): { key: string; label: string }[] {
  const out: { key: string; label: string }[] = [];
  for (let back = 0; back < 12; back += 1) {
    const d = new Date(now.getFullYear(), now.getMonth() - back, 1);
    const p = (n: number) => String(n).padStart(2, "0");
    const key = `${d.getFullYear()}-${p(d.getMonth() + 1)}`;
    // Год в подписи — только у чужого года: двенадцать раз повторить «2026»
    // значит занять строку тем, что и так известно.
    const month = new Intl.DateTimeFormat("ru-RU", { month: "long", timeZone: "Europe/Moscow" })
      .format(new Date(Date.UTC(d.getFullYear(), d.getMonth(), 15)));
    const label = d.getFullYear() === now.getFullYear() ? month : `${month} ${d.getFullYear()}`;
    out.push({ key, label });
  }
  return out;
}

export default async function OwnerPage({
  searchParams,
}: {
  /**
   * Период — в адресе: ссылку на нужный месяц можно переслать, а перезагрузка
   * страницы не возвращает владельца в текущий месяц посреди разбора.
   */
  searchParams: Promise<{ p?: string }>;
}) {
  /**
   * Отказ показываем понятной страницей, а не красным экраном ошибки: без
   * права на выручку этот раздел просто не для этого сотрудника, и это не
   * поломка.
   */
  const session = await getSession();
  if (!(await can(session, "VIEW_REVENUE"))) {
    return (
      <div className="px-7 py-8 max-md:px-5">
        <div className="border-border bg-surface max-w-[560px] rounded-xl border p-5">
          <p className="text-md font-medium">Раздел недоступен</p>
          <p className="text-text-muted mt-2 text-sm leading-relaxed">
            Кабинет владельца показывает выручку клиники. Доступ к нему выдаётся отдельно —
            обратитесь к владельцу или администратору.
          </p>
        </div>
      </div>
    );
  }

  /**
   * Замер каждого блока — в журнал сервера. Какой из четырёх отчётов тянет,
   * по экрану не понять, а гадать по коду мы договорились не гадать.
   */
  /**
   * Какой месяц показываем. Чужое значение в адресе до расчётов не доходит:
   * непонятный ключ — это текущий месяц (`isPeriodKey`).
   */
  const asked = (await searchParams).p;
  const period: PeriodKey = isPeriodKey(asked) ? asked : currentMonthKey();
  const months = monthChoices(new Date());

  const parts = await Promise.all([
    timed("отчёт", () => getOwnerReport(period)),
    timed("динамика", () => getWeeklyDynamics()),
    // Период тот же, что и у остального кабинета: выбранный месяц.
    timed("ассистент", () => getAgentStats(session.companyId, period)),
    /**
     * Экономика курсов — теми же функциями, что во вкладке «Курсы» отчётов.
     * Одна метрика — одна функция (§8).
     */
    timed("курсы", () => getCourseEconomics(session.companyId, period)),
    /**
     * Что ассистент довёл до записи — тем же периодом, что и остальной
     * кабинет. Продажей считается доведённая до администратора заявка, а не
     * любая запись из переписки (lib/metrics/agent-sales.ts).
     */
    timed("продажи ассистента", () => {
      const { from, to } = periodBounds(period);
      return getAgentSales(session.companyId, from, to);
    }),
    /**
     * Перешли ли в систему: доля ответов из платформы против отправленных с
     * телефона клиники. Главный вопрос цикла — без него не узнать, сработало
     * ли остальное.
     */
    timed("переход в систему", () => getAdoption(session.companyId)),
    /**
     * Работает ли прогноз неявки. Без этого числа через месяц никто не
     * скажет, приносит функция пользу или просто мигает пометками.
     */
    timed("прогноз неявки", async () => ({
      quality: await noShowQuality(session.companyId),
      weights: await getWeights(session.companyId),
    })),
    /**
     * Сводка недели: наблюдения уже посчитаны и сохранены понедельничным
     * прогоном. Экран только читает — считать здесь нельзя, иначе владелец
     * увидит одно, а в push придёт другое.
     */
    timed("сводка недели", () => getWeeklyDigests()),
  ] as const);
  logTimings("кабинет владельца", [...parts]);

  const report = parts[0].value;
  const weekly = parts[1].value;
  const agent = parts[2].value;
  const courses = parts[3].value;
  const sales = parts[4].value;
  const adoption = parts[5].value;
  const noShow = parts[6].value;
  const digests = parts[7].value;

  return (
    <>
      <header className="border-border flex-none border-b px-7 py-[18px] max-md:px-5">
        <h1 className="text-xl leading-none font-medium tracking-[-0.015em]">Кабинет владельца</h1>
        {/* Период обязателен в подписи: раздел считал один текущий день, и
            «Неявки 0%» читались как «неявок нет вовсе», хотя в базе их сотня.
            Даты — тоже: окно скользящее, и «30 дней» без границ не проверить,
            а с отчётами за «Месяц» его сравнивают постоянно. */}
        <p className="text-text-muted mt-1 text-xs">
          {report.period.label} · {report.period.from} — {report.period.to} · операционная
          картина дня — на экране «Сегодня»
        </p>
        {/*
          Месяцы — ссылками, а не выпадающим списком: выбранный месяц виден
          сразу, а ссылку на нужный месяц можно переслать. Текущий месяц —
          неполный, и так он и подписан: сравнивать его с прошлым целиком
          нельзя, а не сказать об этом — значит дать сравнить молча.
        */}
        <nav className="mt-2 flex flex-wrap items-center gap-1.5 text-xs">
          {months.map((m) => (
            <Link
              key={m.key}
              href={`/owner?p=${m.key}`}
              className={`rounded-md px-2 py-0.5 ${
                m.key === report.period.key
                  ? "bg-accent text-accent-contrast font-medium"
                  : "text-text-muted hover:bg-hover"
              }`}
            >
              {m.label}
            </Link>
          ))}
          {report.period.key === currentMonthKey() ? (
            <span className="text-text-subtle ml-1">месяц ещё идёт — числа неполные</span>
          ) : null}
        </nav>
      </header>

      <div className="flex-1 overflow-auto px-7 py-6 max-md:px-5">
        <div className="grid grid-cols-2 gap-3 md:grid-cols-4 xl:grid-cols-7">
          <Tile label="Выручка" value={formatMoney(report.revenue)} />
          <Tile label="Средний чек" value={formatMoney(report.avgCheck)} />
          {/* Здесь «Приёмов» — все визиты периода, включая запланированные:
              это объём работы клиники. Сколько из них состоялось — подписью. */}
          <Tile label="Визитов" value={report.appts} hint={`пришли ${report.arrived}`} />
          <Tile label="Первичных" value={report.firstVisits} />
          {/*
            Неявки без числа неразобранных — утверждение, которого мы не
            делали. «0%» означает либо «неявок не было», либо «никто не
            отмечает исход»; разница решающая, и она должна быть на экране.
          */}
          <Tile
            label="Неявки"
            value={`${report.noShowRatePct}%`}
            hint={
              report.unmarked > 0
                ? `не отмечено ${formatNumber(report.unmarked)} приёмов на ${formatMoney(report.unmarkedMoney)}`
                : "все прошедшие приёмы отмечены"
            }
          />
          <Tile label="Загрузка" value={`${report.avgLoadPct}%`} hint="3 кабинета" />
          {/* Единственная плитка не про период: это вся база клиники. Так и
              подписана — иначе она читается как «пациентов за 30 дней». */}
          <Tile
            label="Пациентов в базе"
            value={report.patients.total}
            hint={`новых за период ${report.patients.primary} · без согласия ${report.patients.noConsent}`}
          />
        </div>

        {/*
          Сводка стоит первой и во всю ширину: она отвечает на вопрос «куда
          смотреть», а таблицы ниже — на вопрос «что там». Обратный порядок
          означал бы, что владелец сначала листает цифры, а потом узнаёт, какие
          из них стоило смотреть.
        */}
        <div className="mt-4">
          <WeeklyDigestBlock digests={digests} />
        </div>

        <div className="mt-4 grid grid-cols-1 gap-4 lg:grid-cols-2">
          <section className="border-border bg-surface rounded-xl border p-5">
            <h2 className="text-sm font-medium">Сотрудники: производительность и часы</h2>
            {/* Период у каждой таблицы свой подписью: без него владелец
                сравнивал эти числа с отчётами за другой отрезок. */}
            <p className="text-text-subtle mb-4 text-2xs">
              {report.period.label} · {report.period.from} — {report.period.to}
            </p>
            <div className="-mx-1 overflow-x-auto px-1">
              <table className="w-full min-w-[440px] border-collapse text-sm">
                <thead>
                  <tr className="text-text-subtle text-left text-2xs">
                    <th className="py-2 pr-3 font-normal">Специалист</th>
                    {/* «Пришли», а не «Приёмы»: одно слово — одно число (§8). */}
                    <th className="py-2 pr-3 text-right font-normal">Пришли</th>
                    <th className="py-2 pr-3 text-right font-normal">Часы</th>
                    <th className="py-2 text-right font-normal">Выручка</th>
                  </tr>
                </thead>
                <tbody>
                  {report.staff.map((p) => (
                    <tr key={p.staffId ?? p.name} className="border-border-soft border-t">
                      <td className="py-2.5 pr-3">
                        <div className="font-medium">{p.name}</div>
                        <div className="text-text-subtle text-2xs">
                          {p.noShow > 0 ? `неявок ${p.noShow}` : "неявок нет"}
                          {p.planned ? ` · впереди ${p.planned}` : ""}
                        </div>
                      </td>
                      <td className="num py-2.5 pr-3 text-right">{p.appts}</td>
                      <td className="num py-2.5 pr-3 text-right">{p.hours.toFixed(1)}</td>
                      <td className="num py-2.5 text-right">{formatMoney(p.revenue)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            {/*
              Курсы без специалиста. Они есть в итоге сверху и в разрезе по
              услугам ниже, но приписать их человеку не из чего: сеансов по
              курсу ещё не было, а услугу ведёт не один человек. Без этой
              строки сумма таблицы меньше итога, и разница читается как
              пропавшие деньги.
            */}
            {report.coursesWithoutStaff > 0 ? (
              <p className="text-text-subtle mt-3 text-2xs">
                Ещё {formatMoney(report.coursesWithoutStaff)} — курсы, у которых специалист не
                определился: сеансов по ним пока не было. В выручке и в разрезе по услугам эти
                деньги есть.
              </p>
            ) : null}
          </section>

          <section className="border-border bg-surface rounded-xl border p-5">
            {/* Подпись периода обязательна: тот же показатель за месяц стоит в
                «Отчётах», и без подписи одинаковые заголовки с разными числами
                читаются как ошибка платформы. */}
            <h2 className="text-sm font-medium">Загрузка кабинетов</h2>
            <p className="text-text-subtle mb-4 text-2xs">
              {report.period.label} · {report.period.from} — {report.period.to}
            </p>
            <ul className="flex flex-col gap-3">
              {report.rooms.map((l) => (
                <li key={l.name} className="flex items-center gap-3">
                  <span className="w-40 flex-none truncate text-sm" title={l.name}>{l.name}</span>
                  <span className="bg-list-gap relative h-2 flex-1 overflow-hidden rounded-pill">
                    <span
                      className="bg-accent absolute inset-y-0 left-0 rounded-pill"
                      style={{ width: `${l.ratePct}%` }}
                    />
                  </span>
                  <span className="num text-text-muted w-10 flex-none text-right text-xs">{l.ratePct}%</span>
                </li>
              ))}
            </ul>
            <h3 className="text-text-subtle mt-5 mb-2 text-2xs">Гипотезы — что улучшить</h3>
            <ul className="flex flex-col gap-2">
              {report.hypotheses.map((t, i) => (
                <li key={i} className="text-text-muted flex gap-2 text-sm leading-snug">
                  <span aria-hidden className="text-accent-text flex-none">•</span>
                  <span>{t}</span>
                </li>
              ))}
            </ul>
          </section>
        </div>

        <div className="mt-4">
          <WeeklyCharts data={weekly} />
        </div>

        <section className="border-border bg-surface mt-4 rounded-xl border p-5">
          <div className="mb-4 flex items-baseline justify-between gap-3 max-md:flex-col max-md:items-start max-md:gap-1">
            <div>
              <h2 className="text-sm font-medium">Выручка по услугам</h2>
              <p className="text-text-subtle mt-0.5 text-2xs">
                {report.period.label} · {report.period.from} — {report.period.to}
              </p>
            </div>
            {/* Воронка — за тот же период. Прежде здесь стояли диалоги и звонки
                за всю историю клиники рядом с выручкой за месяц. */}
            <span className="text-text-subtle text-xs">
              за период: переписок {report.funnel.dialogs} · звонков {report.funnel.calls}
            </span>
          </div>
          <div className="-mx-1 overflow-x-auto px-1">
            <table className="w-full min-w-[440px] border-collapse text-sm">
              <thead>
                <tr className="text-text-subtle text-left text-2xs">
                  <th className="py-2 pr-3 font-normal">Услуга</th>
                  {/* «Пришли» — то же слово и то же число, что во всех остальных
                      разрезах: приём это состоявшийся приём (§8). */}
                  <th className="py-2 pr-3 text-right font-normal">Пришли</th>
                  <th className="py-2 text-right font-normal">Выручка</th>
                </tr>
              </thead>
              <tbody>
                {report.services.map((s) => (
                  <tr key={s.service} className="border-border-soft border-t">
                    <td className="py-2 pr-3">{s.service}</td>
                    <td className="num py-2 pr-3 text-right">{s.count}</td>
                    <td className="num py-2 text-right">{formatMoney(s.revenue)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>

        <AgentSales report={sales} periodLabel={`за ${report.period.label.toLowerCase()}`} />

        {/*
          Перешли ли в систему. Главный вопрос цикла: пока администратор
          отвечает с телефона, всё остальное сделано вхолостую.
        */}
        <Adoption data={adoption} />

        <NoShowQualityBlock data={noShow.quality} weightsSet={noShow.weights !== null} />

        <AgentSection
          stats={agent}
          periodLabel={`${report.period.label} · ${report.period.from} — ${report.period.to}`}
        />

        {/*
          Экономика курсов. Обязательства стоят рядом с выручкой месяца, и
          подпись «это не выручка» здесь не украшение: без неё два числа
          складывают.
        */}
        <section className="border-border bg-surface mt-4 rounded-xl border p-5">
          <h2 className="text-sm font-medium">Экономика курсов</h2>
          <p className="text-text-subtle mb-4 text-2xs">
            доходимость и возвраты — за {courses.periodLabel}; обязательства — на сегодня
          </p>
          <CourseEconomicsBlock data={courses} />
        </section>

        <div className="mt-4">
          <OwnerAssistant period={period} />
        </div>
      </div>
    </>
  );
}
